<style>
.notes-studio{max-width:1440px;margin:auto;padding:24px;--notes-ink:var(--text-primary,#172033)}.notes-hero{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:28px;border:1px solid var(--border-glass);border-radius:24px;background:linear-gradient(125deg,#365ce912,#9333ea0a,var(--bg-card,#ffffff));margin-bottom:20px}.notes-hero h1{font-size:30px;font-weight:800;color:var(--notes-ink)}.notes-hero p{color:var(--text-muted);margin-top:6px}.notes-grid{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start}.notes-card{border:1px solid var(--border-glass);border-radius:22px;padding:24px;background:var(--bg-card,#ffffff);min-width:0}.notes-card h2{font-weight:750;font-size:18px;margin-bottom:12px}.notes-card p,.notes-card li{overflow-wrap:anywhere}.notes-label{display:block;font-size:12px;font-weight:650;margin-bottom:8px;color:var(--text-secondary)}.notes-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.notes-hint{font-size:12px;color:var(--text-muted);line-height:1.6}.notes-studio textarea{color:var(--notes-ink);resize:vertical}.notes-studio .theme-input{min-width:0;width:100%}.notes-stack{display:grid;gap:20px}.notes-purpose{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.notes-purpose button{font-size:12px;border:1px solid var(--border-glass);border-radius:12px;padding:10px 12px;color:var(--text-secondary)}.notes-purpose button[aria-pressed=true]{background:#365ce9;color:white;border-color:#365ce9}.notes-wallet{text-align:right;flex-shrink:0}.notes-wallet strong{font-size:24px;color:#365ce9}.notes-metric{border-radius:18px;padding:18px;color:white;background:linear-gradient(135deg,#16428a,#347cff)}.notes-metric:nth-child(2){background:linear-gradient(135deg,#542c8c,#935def)}.notes-metric:nth-child(3){background:linear-gradient(135deg,#075b54,#119a88)}.notes-metric strong{font-size:30px;display:block}.notes-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.notes-history a{display:block;padding:14px 0;border-bottom:1px solid var(--border-glass);color:var(--notes-ink)}.notes-history small{display:block;color:var(--text-muted);margin-top:4px}.notes-task{border:1px solid var(--border-glass);border-radius:16px;padding:16px;display:grid;gap:10px}.notes-task-head{display:flex;gap:10px;justify-content:space-between;align-items:start}.notes-priority{border-radius:8px;padding:4px 8px;font-size:11px;background:#365ce918;color:var(--text-secondary);flex-shrink:0}.notes-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.notes-source{background:var(--bg-input,var(--bg-card,#ffffff));padding:16px;border-radius:16px}.notes-modal{position:fixed;inset:0;background:#0f172a80;z-index:100;display:flex;align-items:center;justify-content:center;padding:20px}.notes-modal .notes-card{width:100%;max-width:520px;max-height:90vh;overflow:auto;background:var(--bg-card,#ffffff)}.notes-result{white-space:pre-wrap;line-height:1.65}.notes-studio details summary{cursor:pointer;font-weight:650}.notes-history{position:sticky;top:100px}.notes-example{font-size:12px;color:#365ce9;text-align:left}.notes-quote{border-radius:12px;background:#365ce910;padding:12px;font-size:13px}.notes-studio .form-chip{border:1px solid var(--border-glass,#dbe1ec);border-radius:12px;padding:10px 14px;background:var(--bg-card,#fff);color:var(--text-secondary,#334155);font-size:13px;display:inline-flex;align-items:center;justify-content:center;gap:6px}.notes-studio button:disabled{opacity:.5;cursor:not-allowed}
@media(max-width:1050px){.notes-grid{grid-template-columns:1fr}.notes-history{position:static}}@media(max-width:640px){.notes-studio{padding:12px}.notes-hero{padding:20px;align-items:start}.notes-hero h1{font-size:23px}.notes-wallet strong{font-size:18px}.notes-card{padding:18px}.notes-columns{grid-template-columns:1fr}.notes-metrics{gap:8px}.notes-metric{padding:12px}.notes-metric strong{font-size:24px}}
</style><style>
.folder-workspace{max-width:1440px;margin:0 auto;padding:0;--folder-ink:var(--text-primary,#172033)}
.folder-head{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:22px;padding:28px;border:1px solid var(--border-glass,#e2e8f0);border-radius:24px;background:radial-gradient(ellipse at top right,color-mix(in srgb,var(--folder-accent) 9%,transparent),transparent 70%),var(--bg-card,#fff);box-shadow:0 12px 40px #12234c05;position:relative;overflow:hidden;margin-bottom:20px}
.folder-head:before{content:'';position:absolute;inset:0 auto 0 0;width:4px;background:var(--folder-accent)}
.folder-heading{display:flex;align-items:center;gap:18px;min-width:0}.folder-emblem{width:62px;height:62px;flex:none;border-radius:18px;display:grid;place-items:center;font-size:25px;color:var(--folder-accent);background:color-mix(in srgb,var(--folder-accent) 10%,transparent);border:1px solid color-mix(in srgb,var(--folder-accent) 20%,transparent)}
.folder-eyebrow{font-size:10px;letter-spacing:.12em;font-weight:700;color:var(--text-muted)}.folder-heading h1{font-size:clamp(24px,3vw,32px);line-height:1.2;letter-spacing:-.035em;font-weight:800;margin:4px 0;color:var(--folder-ink);overflow-wrap:anywhere}.folder-heading p{font-size:13px;line-height:1.6;color:var(--text-muted);overflow-wrap:anywhere}
.folder-create{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.folder-create>a{padding:10px 14px;font-size:12px;display:inline-flex;gap:7px;align-items:center;justify-content:center;border-radius:12px}.folder-create .form-chip,.folder-icon-action{border:1px solid var(--border-glass,#e2e8f0);background:var(--bg-card,#fff);color:var(--text-secondary)}.folder-facts{grid-column:1/-1;display:flex;flex-wrap:wrap;gap:12px 24px;padding-top:18px;border-top:1px solid var(--border-glass,#e2e8f0);font-size:12px;color:var(--text-muted)}.folder-facts strong{color:var(--text-primary);font-weight:700}
.folder-nav{display:flex;gap:5px;padding:6px;background:var(--bg-card,#fff);border:1px solid var(--border-glass,#e2e8f0);border-radius:16px;margin-bottom:24px;flex-wrap:wrap}.folder-nav a{display:flex;gap:7px;align-items:center;padding:10px 13px;font-size:12px;font-weight:600;border-radius:10px;color:var(--text-muted);white-space:nowrap}.folder-nav a[aria-current=page]{color:white;background:linear-gradient(135deg,#5275ff,#3151dd);box-shadow:0 3px 8px #365ce926}.folder-nav a:hover{background:#365ce90b;color:var(--folder-ink)}.folder-nav a[aria-current=page]:hover{color:white;background:#365ce9}.folder-nav span{font-size:10px;background:#94a3b81a;padding:1px 5px;border-radius:5px}.folder-nav a[aria-current=page] span{background:#ffffff26}
.folder-workspace .notes-card{border-radius:18px}.folder-overview-grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(0,1fr);gap:20px}.folder-panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.folder-panel-head h2{margin:0}.folder-panel-head a{font-size:12px;color:var(--accent,#365ce9);font-weight:600}.folder-mini-row{display:flex;gap:12px;align-items:center;padding:14px 0;border-top:1px solid var(--border-glass,#e2e8f0);min-width:0}.folder-mini-icon{width:38px;height:38px;flex:none;border-radius:11px;display:grid;place-items:center;background:#365ce90d;color:#365ce9}.folder-mini-copy{min-width:0;flex:1}.folder-mini-copy strong{display:block;font-size:13px;overflow-wrap:anywhere}.folder-mini-copy small{font-size:11px;color:var(--text-muted)}.folder-mini-stat{text-align:right;font-size:13px;font-weight:700;flex:none}.folder-mini-stat small{display:block;font-size:10px;color:var(--text-muted);font-weight:400}.folder-empty{padding:22px 0;display:grid;justify-items:start;gap:12px}.folder-empty p{font-size:13px;line-height:1.6;color:var(--text-muted);max-width:50ch}.folder-empty .form-chip{font-size:12px}.folder-progress{height:5px;border-radius:8px;background:#94a3b81a;overflow:hidden;margin-top:8px}.folder-progress span{display:block;height:100%;background:#7c54df;border-radius:8px}.folder-workspace .notes-metric{position:relative;overflow:hidden;padding:22px}.folder-workspace .notes-metric i{position:absolute;right:20px;bottom:20px;font-size:42px;opacity:.25}.folder-workspace .notes-metric small{display:block;margin-top:6px;font-size:11px;opacity:.8}
@media(max-width:900px){.folder-head{grid-template-columns:1fr}.folder-create{grid-row:2}.folder-overview-grid{grid-template-columns:1fr}}
@media(max-width:640px){.folder-head{padding:20px;gap:16px;border-radius:18px}.folder-emblem{width:46px;height:46px;font-size:20px;border-radius:14px}.folder-heading{gap:12px}.folder-facts{gap:8px 16px}.folder-nav{gap:3px}.folder-nav a{padding:8px 9px;font-size:11px}.folder-nav a>i{display:none}.folder-workspace .notes-metrics{grid-template-columns:1fr}.folder-workspace .notes-metric{padding:18px}.folder-workspace .notes-metric strong{font-size:28px}}
</style>
<style>
.folder-link-tools{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;margin-bottom:18px}.folder-link-tools h2{font-size:18px;font-weight:750}.folder-link-tools p{font-size:12px;color:var(--text-muted);margin-top:4px}.folder-report-context{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:22px}.folder-report-context>div{padding:18px 22px;border:1px solid var(--border-glass,#e2e8f0);border-radius:16px;background:var(--bg-card,#fff)}.folder-report-context span{font-size:12px;color:var(--text-muted)}.folder-report-context strong{display:block;font-size:25px;font-weight:750;margin:4px 0}.folder-report-context small{font-size:11px;line-height:1.5;display:block;color:var(--text-muted)}@media(max-width:640px){.folder-report-context{grid-template-columns:1fr}.folder-link-tools .folder-create{width:100%}}
</style>
